            tool: "tempera_status",
            description: "Fetch gateway upstream health for every connected product MCP server."
        ),
    ]

    /// The MCP gateway's JSON-RPC error codes.
    public static let mcpErrorCodes = TemperaMcpErrorCodes(
        planLimit: -32002,
        invalidRequest: -32600,
        methodNotFound: -32601,
        invalidParams: -32602,
        internalError: -32603
    )

    /// MCP protocol revision the gateway and this SDK speak.
    public static let mcpProtocolVersion: String = "2026-07-28"
    /// What the unified MCP gateway is.
    public static let mcpDescription: String = "Unified MCP gateway at ${issuer}/mcp: stateless streamable-HTTP JSON-RPC 2.0, audience tempera-mcp with scope mcp:invoke. The model-facing surface is fixed to ten tempera_* fabric verbs; product capabilities are opaque, policy-filtered cards discovered with tempera_search, inspected with tempera_describe, and executed through tempera_invoke or tempera_prepare/tempera_commit. Per-call product execution is metered."

    /// Look up one operation by product key and operation id.
    public static func findOperation(product: String, id: String) -> TemperaOperationSpec? {
        operations.first { $0.product == product && $0.id == id }
    }

    /// Every operation belonging to one product, in declaration order.
    public static func operationsFor(product: String) -> [TemperaOperationSpec] {
        operations.filter { $0.product == product }
    }

    /// Look up one product by registry key.
    public static func findProduct(key: String) -> TemperaProductSpec? {
        products.first { $0.key == key }
    }

    /// Look up one environment preset by name.
    public static func findEnvironment(_ environment: String) -> TemperaEnvironmentTarget? {
        environments.first { $0.environment == environment }
    }

    /// Look up one MCP gateway method by id.
    public static func findMcpMethod(id: String) -> TemperaMcpMethodSpec? {
        mcpMethods.first { $0.id == id }
    }
}

